// Threat map queries (G0 M28 D716, D719). Every query runs inside
// db.InTenantTx and also filters by org_id explicitly.
// Today's evaluation for one scope and framework; a later run the same day
// replaces it.
func (q *Queries) UpsertThreatMapSnapshot(ctx context.Context, arg UpsertThreatMapSnapshotParams) error {
	_, err := q.db.Exec(ctx, upsertThreatMapSnapshot,
		arg.OrgID,
		arg.ScopeKey,
		arg.Framework,
		arg.Day,
		arg.EvaluatedAt,
		arg.CatalogVersion,
		arg.CatalogDigest,
		arg.MappingDigest,
		arg.States,
		arg.Counts,
	)
	return err
}
